from pathlib import Path
import json,hashlib
root=Path.cwd();s=root/'.local/step07-ci-timeout';w=Path(json.loads((s/'runtime-private.json').read_text())['workspace']);p=w/'apps/api/tests/studio/integration.test.ts';old=p.read_text();body=old[old.index("it('R4 real COMMIT first/update/history"):];assert body.endswith('});\n')
setup='''
  const diagEvents: unknown[] = [], pending = new Map<number, { label: string; start: number }>();
  let diagId = 0; const diagStarted = performance.now();
  function diag(event: string, label: string, extra: unknown = null) {
    const item = { elapsedMs: Math.round(performance.now() - diagStarted), event, label, extra };
    diagEvents.push(item); console.log('R4_DIAGNOSTIC ' + JSON.stringify(item));
  }
  async function measured<T>(label: string, fn: Promise<T>): Promise<T> {
    const id = ++diagId, start = performance.now(); pending.set(id, { label, start }); diag('start', label);
    try { const result = await fn; diag('end', label, { ms: Math.round(performance.now()-start) }); return result; }
    catch (error) { diag('error',label,{ms:Math.round(performance.now()-start),message:String(error)}); throw error; }
    finally { pending.delete(id); }
  }
  const heartbeat = setInterval(() => { diag('pending','heartbeat',[...pending.values()].map(x=>({label:x.label,ms:Math.round(performance.now()-x.start)}))); void record('r4-diagnostic-progress',{events:diagEvents}); },10000);
  diag('case','start');
'''
body=body.replace("coherent', async () => {\n", "coherent', async () => {\n"+setup,1)
repls={
 'const browser = await chromium.launch();':"const browser = await measured('browser-launch',chromium.launch());",
